-- The demo seed used an English name for this market; keep one row in Vietnamese.
UPDATE places SET name = 'Chợ Bến Thành' WHERE name = 'Ben Thanh Market';

INSERT INTO places (destination_id, name, category, address, summary, summary_vi, map_query)
SELECT d.id, p.name, p.category, p.address, p.summary, p.summary_vi, p.map_query
FROM destinations d
JOIN (
  SELECT 'Hanoi' AS destination_name, 'Hồ Hoàn Kiếm và đền Ngọc Sơn' AS name, 'Culture' AS category, 'Quận Hoàn Kiếm' AS address, 'The heart of Hanoi, with the red Huc Bridge leading to Ngoc Son Temple.' AS summary, 'Trái tim của Hà Nội, cầu Thê Húc đỏ dẫn vào đền Ngọc Sơn.' AS summary_vi, 'Hồ Hoàn Kiếm và đền Ngọc Sơn, Quận Hoàn Kiếm, Việt Nam' AS map_query
  UNION ALL SELECT 'Hanoi' AS destination_name, 'Phố cổ Hà Nội' AS name, 'Sightseeing' AS category, 'Quận Hoàn Kiếm' AS address, 'Old trade streets, tube houses and endless small food stalls.' AS summary, '36 phố phường với nhà ống, hàng quán và nhịp sống rất riêng.' AS summary_vi, 'Phố cổ Hà Nội, Quận Hoàn Kiếm, Việt Nam' AS map_query
  UNION ALL SELECT 'Hanoi' AS destination_name, 'Văn Miếu – Quốc Tử Giám' AS name, 'Culture' AS category, 'Quận Đống Đa' AS address, 'Vietnam’s first university, with stone steles of doctoral laureates.' AS summary, 'Trường đại học đầu tiên của Việt Nam, nơi lưu giữ bia tiến sĩ.' AS summary_vi, 'Văn Miếu – Quốc Tử Giám, Quận Đống Đa, Việt Nam' AS map_query
  UNION ALL SELECT 'Hanoi' AS destination_name, 'Lăng Chủ tịch Hồ Chí Minh' AS name, 'Culture' AS category, 'Quận Ba Đình' AS address, 'Ba Dinh Square, the mausoleum, One Pillar Pagoda and the Presidential Palace area.' AS summary, 'Quảng trường Ba Đình, lăng Bác, chùa Một Cột và khu Phủ Chủ tịch.' AS summary_vi, 'Lăng Chủ tịch Hồ Chí Minh, Quận Ba Đình, Việt Nam' AS map_query
  UNION ALL SELECT 'Hanoi' AS destination_name, 'Bảo tàng Dân tộc học Việt Nam' AS name, 'Culture' AS category, 'Quận Cầu Giấy' AS address, 'Life of the 54 ethnic groups, with full-size traditional houses outside.' AS summary, 'Đời sống 54 dân tộc, có cả khu nhà truyền thống ngoài trời.' AS summary_vi, 'Bảo tàng Dân tộc học Việt Nam, Quận Cầu Giấy, Việt Nam' AS map_query
  UNION ALL SELECT 'Hanoi' AS destination_name, 'Hồ Tây' AS name, 'Nature' AS category, 'Quận Tây Hồ' AS address, 'The largest lake in Hanoi, best at sunset by Tran Quoc Pagoda.' AS summary, 'Hồ lớn nhất Hà Nội, đẹp nhất lúc hoàng hôn bên chùa Trấn Quốc.' AS summary_vi, 'Hồ Tây, Quận Tây Hồ, Việt Nam' AS map_query
  UNION ALL SELECT 'Hanoi' AS destination_name, 'Phố Tạ Hiện' AS name, 'Food' AS category, 'Quận Hoàn Kiếm' AS address, 'Lively evening street for beer, snacks and people-watching.' AS summary, 'Phố bia, đồ nhắm và không khí sôi động về đêm.' AS summary_vi, 'Phố Tạ Hiện, Quận Hoàn Kiếm, Việt Nam' AS map_query
  UNION ALL SELECT 'Hai Phong' AS destination_name, 'Đảo Cát Bà' AS name, 'Nature' AS category, 'Huyện Cát Hải' AS address, 'Island with a national park, beaches and boat trips.' AS summary, 'Đảo lớn có vườn quốc gia, bãi tắm và tour thuyền.' AS summary_vi, 'Đảo Cát Bà, Huyện Cát Hải, Việt Nam' AS map_query
