  UNION ALL SELECT 'Tay Ninh' AS destination_name, 'Hồ Dầu Tiếng' AS name, 'Nature' AS category, 'Dương Minh Châu' AS address, 'Large reservoir at sunset.' AS summary, 'Hồ nước lớn, đẹp lúc hoàng hôn.' AS summary_vi, 'Hồ Dầu Tiếng, Dương Minh Châu, Việt Nam' AS map_query
  UNION ALL SELECT 'Tay Ninh' AS destination_name, 'Chùa Gò Kén' AS name, 'Culture' AS category, 'Hòa Thành' AS address, 'Old pagoda in Tay Ninh.' AS summary, 'Ngôi chùa cổ ở Tây Ninh.' AS summary_vi, 'Chùa Gò Kén, Hòa Thành, Việt Nam' AS map_query
  UNION ALL SELECT 'Tay Ninh' AS destination_name, 'Căn cứ Trung ương Cục miền Nam' AS name, 'Culture' AS category, 'Tân Biên' AS address, 'Wartime forest headquarters.' AS summary, 'Di tích căn cứ trong rừng thời kháng chiến.' AS summary_vi, 'Căn cứ Trung ương Cục miền Nam, Tân Biên, Việt Nam' AS map_query
