  UNION ALL SELECT 'Vinh Long' AS destination_name, 'Kẹo dừa Bến Tre' AS name, 'Food' AS category, 'Bến Tre' AS address, 'The famous local coconut candy.' AS summary, 'Kẹo dừa đặc sản xứ dừa.' AS summary_vi, 'Kẹo dừa Bến Tre, Bến Tre, Việt Nam' AS map_query
