  UNION ALL SELECT 'Dong Thap' AS destination_name, 'Vườn quốc gia Tràm Chim' AS name, 'Nature' AS category, 'Tam Nông' AS address, 'Wetland of birds and red-crowned cranes.' AS summary, 'Vùng ngập nước với chim, sếu đầu đỏ.' AS summary_vi, 'Vườn quốc gia Tràm Chim, Tam Nông, Việt Nam' AS map_query
  UNION ALL SELECT 'Dong Thap' AS destination_name, 'Làng hoa Sa Đéc' AS name, 'Nature' AS category, 'Sa Đéc' AS address, 'Flower village busiest before Tet.' AS summary, 'Làng hoa rực rỡ nhất dịp Tết.' AS summary_vi, 'Làng hoa Sa Đéc, Sa Đéc, Việt Nam' AS map_query
