  UNION ALL SELECT 'Dong Thap' AS destination_name, 'Nhà cổ Huỳnh Thủy Lê' AS name, 'Culture' AS category, 'Sa Đéc' AS address, 'House from the novel The Lover.' AS summary, 'Ngôi nhà gắn với tiểu thuyết “Người tình”.' AS summary_vi, 'Nhà cổ Huỳnh Thủy Lê, Sa Đéc, Việt Nam' AS map_query
  UNION ALL SELECT 'Dong Thap' AS destination_name, 'Chùa Vĩnh Tràng' AS name, 'Culture' AS category, 'Mỹ Tho (Tiền Giang cũ)' AS address, 'Large pagoda mixing styles.' AS summary, 'Ngôi chùa lớn kết hợp nhiều kiến trúc.' AS summary_vi, 'Chùa Vĩnh Tràng, Mỹ Tho (Tiền Giang cũ), Việt Nam' AS map_query
