  UNION ALL SELECT 'Dong Thap' AS destination_name, 'Chợ nổi Cái Bè' AS name, 'Sightseeing' AS category, 'Cái Bè (Tiền Giang cũ)' AS address, 'Floating market on the Tien River.' AS summary, 'Chợ nổi trên sông Tiền.' AS summary_vi, 'Chợ nổi Cái Bè, Cái Bè (Tiền Giang cũ), Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Miếu Bà Chúa Xứ Núi Sam' AS name, 'Culture' AS category, 'Châu Đốc' AS address, 'Major pilgrimage temple.' AS summary, 'Ngôi miếu linh thiêng, khách hành hương đông.' AS summary_vi, 'Miếu Bà Chúa Xứ Núi Sam, Châu Đốc, Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Rừng tràm Trà Sư' AS name, 'Nature' AS category, 'Tịnh Biên' AS address, 'Green cajuput forest by boat.' AS summary, 'Rừng tràm phủ bèo xanh, đi xuồng.' AS summary_vi, 'Rừng tràm Trà Sư, Tịnh Biên, Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Núi Cấm' AS name, 'Nature' AS category, 'Tịnh Biên' AS address, 'Highest mountain in the delta.' AS summary, 'Nóc nhà miền Tây, có cáp treo.' AS summary_vi, 'Núi Cấm, Tịnh Biên, Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Chợ nổi Long Xuyên' AS name, 'Sightseeing' AS category, 'Long Xuyên' AS address, 'Floating market at dawn.' AS summary, 'Chợ nổi buổi sớm.' AS summary_vi, 'Chợ nổi Long Xuyên, Long Xuyên, Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Đảo Phú Quốc' AS name, 'Beach' AS category, 'Phú Quốc (Kiên Giang cũ)' AS address, 'Large island of beaches and sunsets.' AS summary, 'Đảo ngọc với biển xanh và hoàng hôn.' AS summary_vi, 'Đảo Phú Quốc, Phú Quốc (Kiên Giang cũ), Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Quần đảo Nam Du' AS name, 'Beach' AS category, 'Kiên Hải (Kiên Giang cũ)' AS address, 'Remote islands with clear water.' AS summary, 'Quần đảo hoang sơ, nước trong vắt.' AS summary_vi, 'Quần đảo Nam Du, Kiên Hải (Kiên Giang cũ), Việt Nam' AS map_query
  UNION ALL SELECT 'An Giang' AS destination_name, 'Thạch Động Hà Tiên' AS name, 'Nature' AS category, 'Hà Tiên (Kiên Giang cũ)' AS address, 'Cave pagoda in a limestone hill.' AS summary, 'Hang động có chùa trong núi đá.' AS summary_vi, 'Thạch Động Hà Tiên, Hà Tiên (Kiên Giang cũ), Việt Nam' AS map_query
  UNION ALL SELECT 'Ca Mau' AS destination_name, 'Mũi Cà Mau' AS name, 'Nature' AS category, 'Ngọc Hiển' AS address, 'Southernmost point and mangrove park.' AS summary, 'Điểm cực Nam Tổ quốc, rừng đước bạt ngàn.' AS summary_vi, 'Mũi Cà Mau, Ngọc Hiển, Việt Nam' AS map_query
  UNION ALL SELECT 'Ca Mau' AS destination_name, 'Vườn quốc gia U Minh Hạ' AS name, 'Nature' AS category, 'U Minh' AS address, 'Peat swamp forest of cajuput.' AS summary, 'Rừng tràm ngập nước U Minh.' AS summary_vi, 'Vườn quốc gia U Minh Hạ, U Minh, Việt Nam' AS map_query
  UNION ALL SELECT 'Ca Mau' AS destination_name, 'Hòn Đá Bạc' AS name, 'Nature' AS category, 'Trần Văn Thời' AS address, 'Rocky islet off the coast.' AS summary, 'Cụm đảo đá ven biển Cà Mau.' AS summary_vi, 'Hòn Đá Bạc, Trần Văn Thời, Việt Nam' AS map_query
  UNION ALL SELECT 'Ca Mau' AS destination_name, 'Nhà Công tử Bạc Liêu' AS name, 'Culture' AS category, 'Bạc Liêu' AS address, 'Mansion of the famous rich young man.' AS summary, 'Dinh thự của “Công tử Bạc Liêu”.' AS summary_vi, 'Nhà Công tử Bạc Liêu, Bạc Liêu, Việt Nam' AS map_query
  UNION ALL SELECT 'Ca Mau' AS destination_name, 'Cánh đồng điện gió Bạc Liêu' AS name, 'Sightseeing' AS category, 'Bạc Liêu' AS address, 'Wind turbines standing in the sea.' AS summary, 'Hàng cột điện gió giữa biển.' AS summary_vi, 'Cánh đồng điện gió Bạc Liêu, Bạc Liêu, Việt Nam' AS map_query
  UNION ALL SELECT 'Ca Mau' AS destination_name, 'Khu lưu niệm Cao Văn Lầu' AS name, 'Culture' AS category, 'Bạc Liêu' AS address, 'Memorial to the composer of Da Co Hoai Lang.' AS summary, 'Nơi lưu niệm tác giả “Dạ cổ hoài lang”.' AS summary_vi, 'Khu lưu niệm Cao Văn Lầu, Bạc Liêu, Việt Nam' AS map_query
) p ON d.name = p.destination_name AND d.country = 'Vietnam' AND d.custom_trip_id IS NULL
ON DUPLICATE KEY UPDATE category = VALUES(category), address = VALUES(address), summary = VALUES(summary),
  summary_vi = VALUES(summary_vi), map_query = VALUES(map_query);
